# ruff: noqa: E501
"""Admit only receipt-proven Human continuations of an actual variant definition.

The predecessor function is frozen verbatim from the actual s0_0755 catalog.
CREATE OR REPLACE preserves its ordinary owner and owner-only EXECUTE ACL.
"""

PREDECESSOR_DERIVATION_SCOPE = "CREATE OR REPLACE FUNCTION public.m3_derivation_scope_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE payload jsonb; canonical definition_revisions; parent definition_revisions; decision_id uuid; linked_variant product_variants;\nBEGIN\n payload=to_jsonb(NEW);\n IF TG_TABLE_NAME='definition_revisions' THEN\n  SELECT * INTO STRICT canonical FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND id=NEW.id;\n  IF canonical.visibility='category' AND NOT EXISTS(SELECT 1 FROM products model WHERE model.tenant_id=canonical.tenant_id\n   AND model.category_id=canonical.category_id AND model.id=canonical.product_id AND model.visibility='category') THEN\n   RAISE EXCEPTION 'private model cannot create shared definition' USING ERRCODE='23514'; END IF;\n  IF canonical.parent_definition_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM definition_revisions previous\n   WHERE previous.tenant_id=canonical.tenant_id AND previous.category_id=canonical.category_id AND previous.id=canonical.parent_definition_id\n    AND previous.product_id=canonical.product_id AND previous.variant_id IS NOT DISTINCT FROM canonical.variant_id) THEN\n   RAISE EXCEPTION 'definition continuation parent scope mismatch' USING ERRCODE='23514'; END IF;\n  IF canonical.status='published' AND NOT m3_published_baseline(canonical.tenant_id,canonical.category_id,canonical.product_id,canonical.id,canonical.revision) THEN\n   RAISE EXCEPTION 'published definition receipt mismatch' USING ERRCODE='23514'; END IF;\n  IF canonical.derived_from_definition_id IS NOT NULL THEN\n   SELECT * INTO STRICT parent FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=canonical.derived_from_definition_id;\n   IF NOT m3_published_baseline(parent.tenant_id,parent.category_id,parent.product_id,parent.id,canonical.derived_from_definition_revision)\n    OR canonical.g0_decision_id IS NULL THEN RAISE EXCEPTION 'definition derivation baseline mismatch' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF canonical.variant_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM product_variants variant WHERE variant.tenant_id=NEW.tenant_id\n   AND variant.category_id=NEW.category_id AND variant.id=canonical.variant_id AND variant.product_id=canonical.product_id\n   AND variant.g0_decision_id=canonical.g0_decision_id) THEN RAISE EXCEPTION 'definition variant scope mismatch' USING ERRCODE='23514'; END IF;\n  decision_id=canonical.g0_decision_id;\n ELSIF TG_TABLE_NAME='product_variants' THEN decision_id=NEW.g0_decision_id;\n ELSIF TG_TABLE_NAME='variant_revisions' THEN\n  IF NEW.definition_id IS NULL THEN RETURN NULL; END IF;\n  SELECT * INTO STRICT canonical FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.definition_id;\n  IF canonical.variant_id IS DISTINCT FROM NEW.variant_id OR canonical.product_id IS DISTINCT FROM NEW.product_id\n   OR canonical.revision IS DISTINCT FROM NEW.revision OR canonical.g0_decision_id IS NULL\n   OR NEW.effective_definition IS DISTINCT FROM jsonb_build_object('definition_id',canonical.id,'definition_revision',canonical.revision) THEN\n   RAISE EXCEPTION 'variant snapshot must reference canonical definition' USING ERRCODE='23514'; END IF;\n  decision_id=canonical.g0_decision_id;\n ELSIF TG_TABLE_NAME='project_product_links' THEN\n  SELECT * INTO STRICT canonical FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.definition_id;\n  IF canonical.product_id IS DISTINCT FROM NEW.product_id OR canonical.variant_id IS DISTINCT FROM NEW.variant_id\n   OR canonical.revision IS DISTINCT FROM NEW.definition_revision THEN\n   RAISE EXCEPTION 'project definition variant scope mismatch' USING ERRCODE='23514'; END IF;\n  decision_id=canonical.g0_decision_id;\n ELSIF TG_TABLE_NAME='products' THEN\n  IF NEW.parent_product_id IS NULL THEN RETURN NULL; END IF;\n  SELECT actual.id INTO STRICT decision_id FROM proposal_decisions actual WHERE actual.tenant_id=NEW.tenant_id AND actual.category_id=NEW.category_id\n   AND actual.created_product_id=NEW.id AND actual.created_variant_id IS NULL AND actual.outcome='approved';\n END IF;\n IF decision_id IS NOT NULL THEN PERFORM m3_g0_derivation_assert(NEW.tenant_id,NEW.category_id,decision_id); END IF;\n RETURN NULL;\nEND $function$\n"

DERIVATION_SCOPE = "CREATE OR REPLACE FUNCTION public.m3_derivation_scope_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE payload jsonb; canonical definition_revisions; parent definition_revisions; decision_id uuid; linked_variant product_variants;\n continuation_receipt action_receipts; definition_xmin xid; expected_intent jsonb;\nBEGIN\n payload=to_jsonb(NEW);\n IF TG_TABLE_NAME='definition_revisions' THEN\n  SELECT * INTO STRICT canonical FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND id=NEW.id;\n  IF canonical.visibility='category' AND NOT EXISTS(SELECT 1 FROM products model WHERE model.tenant_id=canonical.tenant_id\n   AND model.category_id=canonical.category_id AND model.id=canonical.product_id AND model.visibility='category') THEN\n   RAISE EXCEPTION 'private model cannot create shared definition' USING ERRCODE='23514'; END IF;\n  IF canonical.parent_definition_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM definition_revisions previous\n   WHERE previous.tenant_id=canonical.tenant_id AND previous.category_id=canonical.category_id AND previous.id=canonical.parent_definition_id\n    AND previous.product_id=canonical.product_id AND previous.variant_id IS NOT DISTINCT FROM canonical.variant_id) THEN\n   RAISE EXCEPTION 'definition continuation parent scope mismatch' USING ERRCODE='23514'; END IF;\n  IF canonical.status='published' AND NOT m3_published_baseline(canonical.tenant_id,canonical.category_id,canonical.product_id,canonical.id,canonical.revision) THEN\n   RAISE EXCEPTION 'published definition receipt mismatch' USING ERRCODE='23514'; END IF;\n  IF canonical.derived_from_definition_id IS NOT NULL THEN\n   SELECT * INTO STRICT parent FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=canonical.derived_from_definition_id;\n   IF NOT m3_published_baseline(parent.tenant_id,parent.category_id,parent.product_id,parent.id,canonical.derived_from_definition_revision)\n    OR canonical.g0_decision_id IS NULL THEN RAISE EXCEPTION 'definition derivation baseline mismatch' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF canonical.variant_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM product_variants variant WHERE variant.tenant_id=NEW.tenant_id\n   AND variant.category_id=NEW.category_id AND variant.id=canonical.variant_id AND variant.product_id=canonical.product_id\n   AND variant.g0_decision_id=canonical.g0_decision_id) THEN\n   -- A native continuation is its own draft; no G0 or publication credential is inherited.\n   IF TG_OP<>'INSERT' OR canonical.status<>'draft' OR canonical.sealed\n    OR canonical.parent_definition_id IS NULL OR canonical.g0_decision_id IS NOT NULL\n    OR canonical.publication_receipt_id IS NOT NULL OR canonical.source_proposal_id IS NOT NULL\n    OR canonical.source_submission_id IS NOT NULL OR canonical.source_proposal_revision IS NOT NULL\n    OR canonical.derived_from_definition_id IS NOT NULL OR canonical.derived_from_definition_revision IS NOT NULL\n    OR canonical.owner_id IS DISTINCT FROM scope_requester() OR scope_actor() IS DISTINCT FROM scope_requester()\n    OR category_access(canonical.tenant_id,canonical.category_id,true) IS DISTINCT FROM true\n    OR NOT EXISTS(SELECT 1 FROM principals actor WHERE actor.tenant_id=canonical.tenant_id\n     AND actor.id=scope_actor() AND actor.kind='human' AND actor.active)\n    OR NOT EXISTS(SELECT 1 FROM products model WHERE model.tenant_id=canonical.tenant_id\n     AND model.category_id=canonical.category_id AND model.id=canonical.product_id\n     AND source_object_audience(canonical.tenant_id,canonical.category_id,'products',model.id,model.owner_id,model.visibility))\n    OR NOT EXISTS(SELECT 1 FROM product_variants variant WHERE variant.tenant_id=canonical.tenant_id\n     AND variant.category_id=canonical.category_id AND variant.product_id=canonical.product_id AND variant.id=canonical.variant_id) THEN\n    RAISE EXCEPTION 'definition variant scope mismatch' USING ERRCODE='23514'; END IF;\n   SELECT previous.* INTO parent FROM definition_revisions previous WHERE previous.tenant_id=canonical.tenant_id\n    AND previous.category_id=canonical.category_id AND previous.product_id=canonical.product_id\n    AND previous.variant_id=canonical.variant_id AND previous.id=canonical.parent_definition_id;\n   IF NOT FOUND THEN RAISE EXCEPTION 'definition continuation requires actual variant parent' USING ERRCODE='23514'; END IF;\n   IF canonical.revision IS DISTINCT FROM parent.revision+1\n    OR EXISTS(SELECT 1 FROM definition_revisions later WHERE later.tenant_id=parent.tenant_id\n     AND later.category_id=parent.category_id AND later.product_id=parent.product_id\n     AND later.variant_id=parent.variant_id AND later.id<>canonical.id AND later.revision>parent.revision)\n    OR source_object_audience(parent.tenant_id,parent.category_id,'definition_revisions',parent.id,parent.owner_id,parent.visibility) IS DISTINCT FROM true\n    OR ROW(canonical.title,canonical.purpose,canonical.visibility,canonical.use_cases,canonical.requirements,\n       canonical.constraints,canonical.unknowns,canonical.exclusions)\n     IS DISTINCT FROM ROW(parent.title,parent.purpose,parent.visibility,parent.use_cases,parent.requirements,\n       parent.constraints,parent.unknowns,parent.exclusions) THEN\n    RAISE EXCEPTION 'definition continuation differs from fixed parent' USING ERRCODE='23514'; END IF;\n   SELECT xmin INTO definition_xmin FROM definition_revisions WHERE tenant_id=canonical.tenant_id AND id=canonical.id;\n   SELECT receipt.* INTO continuation_receipt FROM action_receipts receipt WHERE receipt.tenant_id=canonical.tenant_id\n    AND receipt.category_id=canonical.category_id AND receipt.product_id=canonical.product_id\n    AND receipt.operation='product.definition.draft' AND receipt.subject_type='definition_revision'\n    AND receipt.subject_id=canonical.id AND receipt.subject_revision=canonical.revision AND receipt.xmin=definition_xmin;\n   IF NOT FOUND THEN RAISE EXCEPTION 'definition continuation requires actual creation receipt' USING ERRCODE='23514'; END IF;\n   -- This legacy native handler has no named_actor semantic member. The inherit\n   -- DTO retains its private default while the persisted visibility comes from the parent.\n   expected_intent=jsonb_build_object('operation','product.definition.draft',\n    'category',canonical.category_id,'product',canonical.product_id,\n    'payload',jsonb_build_object('mode','inherit_parent','parent_definition_id',parent.id,\n     'expected_parent_revision',parent.revision,'change_reason',canonical.change_reason),\n    'source_revision',NULL,'private_owner',canonical.owner_id);\n   IF continuation_receipt.actor_id IS DISTINCT FROM scope_actor()\n    OR continuation_receipt.requester_id IS DISTINCT FROM canonical.owner_id\n    OR continuation_receipt.agent_run_id IS NOT NULL OR continuation_receipt.run_id IS NOT NULL\n    OR continuation_receipt.confirmation_id IS NOT NULL\n    OR continuation_receipt.visibility IS DISTINCT FROM canonical.visibility\n    OR continuation_receipt.intent_digest IS DISTINCT FROM encode(sha256(convert_to(kernel_read_canonical_json(expected_intent),'UTF8')),'hex')\n    OR continuation_receipt.result->>'id' IS DISTINCT FROM canonical.id::text\n    OR continuation_receipt.result->'revision' IS DISTINCT FROM to_jsonb(canonical.revision)\n    OR continuation_receipt.result->>'status' IS DISTINCT FROM 'draft'\n    OR continuation_receipt.result->>'inherited_from' IS DISTINCT FROM parent.id::text\n    OR jsonb_typeof(continuation_receipt.result->'item_copies') IS DISTINCT FROM 'array' THEN\n    RAISE EXCEPTION 'definition continuation receipt or inherit payload mismatch' USING ERRCODE='23514'; END IF;\n   -- Prove the complete copied set, including the empty-parent case. Existing item\n   -- atoms still own source validity and original per-item provenance checks.\n   IF (SELECT count(*) FROM definition_specs spec WHERE spec.tenant_id=canonical.tenant_id AND spec.definition_id=canonical.id)\n      <> (SELECT count(*) FROM definition_spec_current current WHERE current.tenant_id=parent.tenant_id\n       AND current.definition_id=parent.id AND NOT current.removed)\n    OR EXISTS(SELECT 1 FROM definition_specs copied WHERE copied.tenant_id=canonical.tenant_id AND copied.definition_id=canonical.id\n     AND (copied.receipt_id IS DISTINCT FROM continuation_receipt.id OR copied.xmin IS DISTINCT FROM definition_xmin\n      OR copied.item_id<>copied.id OR copied.item_version<>1 OR copied.removed\n      OR NOT EXISTS(SELECT 1 FROM definition_spec_current current JOIN definition_specs previous\n       ON previous.tenant_id=current.tenant_id AND previous.id=current.current_row_id\n       WHERE current.tenant_id=parent.tenant_id AND current.definition_id=parent.id AND NOT current.removed\n        AND (to_jsonb(copied)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','receipt_id'])\n         IS NOT DISTINCT FROM (to_jsonb(previous)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','receipt_id']))))\n    OR (SELECT coalesce(jsonb_agg(value ORDER BY value->>'row_id'),'[]') FROM jsonb_array_elements(continuation_receipt.result->'item_copies'))\n      IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('row_id',copied.id,'parent_row_id',previous.id) ORDER BY copied.id),'[]')\n       FROM definition_specs copied JOIN definition_spec_current current ON current.tenant_id=copied.tenant_id\n        AND current.definition_id=parent.id AND current.key=copied.key AND NOT current.removed\n       JOIN definition_specs previous ON previous.tenant_id=current.tenant_id AND previous.id=current.current_row_id\n       WHERE copied.tenant_id=canonical.tenant_id AND copied.definition_id=canonical.id)\n    OR EXISTS((SELECT to_jsonb(source)-ARRAY['id','definition_id','created_at'] FROM definition_sources source\n       WHERE source.tenant_id=canonical.tenant_id AND source.definition_id=canonical.id\n      EXCEPT ALL SELECT to_jsonb(source)-ARRAY['id','definition_id','created_at'] FROM definition_sources source\n       WHERE source.tenant_id=parent.tenant_id AND source.definition_id=parent.id)\n     UNION ALL (SELECT to_jsonb(source)-ARRAY['id','definition_id','created_at'] FROM definition_sources source\n       WHERE source.tenant_id=parent.tenant_id AND source.definition_id=parent.id\n      EXCEPT ALL SELECT to_jsonb(source)-ARRAY['id','definition_id','created_at'] FROM definition_sources source\n       WHERE source.tenant_id=canonical.tenant_id AND source.definition_id=canonical.id)) THEN\n    RAISE EXCEPTION 'definition continuation requires complete exact inherited rows' USING ERRCODE='23514'; END IF;\n  END IF;\n  decision_id=canonical.g0_decision_id;\n ELSIF TG_TABLE_NAME='product_variants' THEN decision_id=NEW.g0_decision_id;\n ELSIF TG_TABLE_NAME='variant_revisions' THEN\n  IF NEW.definition_id IS NULL THEN RETURN NULL; END IF;\n  SELECT * INTO STRICT canonical FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.definition_id;\n  IF canonical.variant_id IS DISTINCT FROM NEW.variant_id OR canonical.product_id IS DISTINCT FROM NEW.product_id\n   OR canonical.revision IS DISTINCT FROM NEW.revision OR canonical.g0_decision_id IS NULL\n   OR NEW.effective_definition IS DISTINCT FROM jsonb_build_object('definition_id',canonical.id,'definition_revision',canonical.revision) THEN\n   RAISE EXCEPTION 'variant snapshot must reference canonical definition' USING ERRCODE='23514'; END IF;\n  decision_id=canonical.g0_decision_id;\n ELSIF TG_TABLE_NAME='project_product_links' THEN\n  SELECT * INTO STRICT canonical FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.definition_id;\n  IF canonical.product_id IS DISTINCT FROM NEW.product_id OR canonical.variant_id IS DISTINCT FROM NEW.variant_id\n   OR canonical.revision IS DISTINCT FROM NEW.definition_revision THEN\n   RAISE EXCEPTION 'project definition variant scope mismatch' USING ERRCODE='23514'; END IF;\n  decision_id=canonical.g0_decision_id;\n ELSIF TG_TABLE_NAME='products' THEN\n  IF NEW.parent_product_id IS NULL THEN RETURN NULL; END IF;\n  SELECT actual.id INTO STRICT decision_id FROM proposal_decisions actual WHERE actual.tenant_id=NEW.tenant_id AND actual.category_id=NEW.category_id\n   AND actual.created_product_id=NEW.id AND actual.created_variant_id IS NULL AND actual.outcome='approved';\n END IF;\n IF decision_id IS NOT NULL THEN PERFORM m3_g0_derivation_assert(NEW.tenant_id,NEW.category_id,decision_id); END IF;\n RETURN NULL;\nEND $function$\n"

DOWN_PREFLIGHT = "DO $block$\nBEGIN\n IF EXISTS(SELECT 1 FROM public.definition_revisions definition\n  WHERE definition.variant_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.product_variants variant\n   WHERE variant.tenant_id=definition.tenant_id AND variant.category_id=definition.category_id\n    AND variant.product_id=definition.product_id AND variant.id=definition.variant_id\n    AND variant.g0_decision_id=definition.g0_decision_id)) THEN\n  RAISE EXCEPTION 'Cannot downgrade while independent variant definition continuations exist' USING ERRCODE='23514';\n END IF;\nEND $block$;\n"

SCHEMA_SQL = (DERIVATION_SCOPE,)

DOWNGRADE_SQL = (DOWN_PREFLIGHT, PREDECESSOR_DERIVATION_SCOPE)
